<section class="wrap section admin"><div class="page-title"><span class="eyebrow">CONTROL ROOM</span><h1>KitVerse admin<span class="dot">.</span></h1><p>Manage the catalog and keep orders moving.</p></div><div class="admin-tabs"><a class="<?=$tab==='overview'?'active':''?>" href="<?=path('admin')?>">Overview</a><a class="<?=$tab==='products'?'active':''?>" href="<?=path('admin',['tab'=>'products'])?>">Products</a><a class="<?=$tab==='catalog'?'active':''?>" href="<?=path('admin',['tab'=>'catalog'])?>">Catalog</a><a class="<?=$tab==='orders'?'active':''?>" href="<?=path('admin',['tab'=>'orders'])?>">Orders</a></div>
