description']??'')?></textarea></label><label class="check"><input type="checkbox" name="is_featured" <?=($product['is_featured']??0)?'checked':''?>> Featured</label><label class="check"><input type="checkbox" name="status" <?=($product['status']??1)?'checked':''?>> Active</label><button class="btn lime full">SAVE PRODUCT</button></form><?php if($product):?><h2>Sizes and stock</h2><?php $s=db()->prepare('SELECT * FROM product_variants WHERE product_id=? ORDER BY FIELD(size,"XS","S","M","L","XL","XXL")');$s->execute([$product['id']]);foreach($s as $variant):?><div class="admin-row"><b><?=e($variant['size'])?></b><span><?=e($variant['sku'])?></span><span><?=$variant['stock']?> in stock</span></div><?php endforeach;?><form method="post" class="form"><input type="hidden" name="csrf" value="<?=token()?>"><input type="hidden" name="action" value="admin_variant"><input type="hidden" name="product_id" value="<?=$product['id']?>"><div class="two"><label>SIZE<select name="size"><?php foreach(['XS','S','M','L','XL','XXL'] as $size):?><option><?=$size?></option><?php endforeach;?></select></label><label>STOCK<input type="number" name="stock" min="0" required></label></div><div class="two"><label>SKU<input name="sku" placeholder="Auto generated"></label><label>PRICE OVERRIDE<input type="number" name="price" min="0" step="0.01"></label></div><button class="btn dark">SAVE SIZE / STOCK</button></form><?php endif;?></div><div class="admin-panel"><h2>All products</h2><?php foreach(db()->query('SELECT id,name,base_price,status FROM products ORDER BY id DESC') as $row):?><a class="admin-row" href="<?=path('admin',['tab'=>'products','edit'=>$row['id']])?>"><span><?=e($row['name'])?></span><b><?=price($row['base_price'])?></b><span><?=$row['status']?'Active':'Hidden'?></span></a><?php endforeach;?></div></div>
<?php elseif($tab==='catalog'):?><div class="catalog-grid"><?php foreach(['leagues'=>'Leagues','clubs'=>'Clubs','categories'=>'Categories'] as $type=>$label):?><div class="admin-panel"><h2><?=$label?></h2><form method="post" class="form"><input type="hidden" name="csrf" value="<?=token()?>"><input type="hidden" name="action" value="admin_catalog"><input type="hidden" name="type" value="<?=$type?>"><label>NAME<input name="name" required></label><?php if($type==='clubs'):?><label>LEAGUE<select name="league_id" required><?php foreach($leagues as $row):?><option value="<?=$row['id']?>"><?=e($row['name'])?></option><?php endforeach;?></select></label><?php elseif($type==='leagues'):?><label>COUNTRY<input name="country"></label><?php else:?><label>DESCRIPTION<input name="description"></label><?php endif;?><button class="btn dark full">ADD <?=strtoupper(substr($label,0,-1))?></button></form><div class="catalog-list"><?php foreach($$type as $row):?><p><?=e($row['name'])?></p><?php endforeach;?></div></div><?php endforeach;?></div>
<?php elseif($tab==='orders'):?><div class="admin-panel"><h2>All orders</h2><?php $orders=db()->query('SELECT * FROM orders ORDER BY id DESC')->fetchAll();if(!$orders):?><p>No orders yet.</p><?php endif;foreach($orders as $order):?><div class="order-admin"><div><b><?=e($order['order_no'])?></b><p><?=e($order['customer_name'])?> · <?=e($order['phone'])?></p><p><?=e($order['address'])?></p><small><?=e($order['created_at'])?> · <?=e(strtoupper($order['payment_method']))?> · <?=e($order['payment_status'])?></small></div><b><?=price($order['total'])?></b><form method="post"><input type="hidden" name="csrf" value="<?=token()?>"><input type="hidden" name="action" value="admin_order"><input type="hidden" name="id" value="<?=$order['id']?>"><select name="status"><?php foreach(['pending','confirmed','processing','packed','shipped','delivered','cancelled'] as $status):?><option value="<?=$status?>" <?=$order['order_status']===$status?'selected':''?>><?=ucfirst($status)?></option><?php endforeach;?></select><button class="btn dark">UPDATE</button></form></div><?php endforeach;?></div>
